#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

struct mod_int {
    int val;

    mod_int(long long v = 0) {
        v %= MOD;
        if (v < 0) v += MOD;
        val = v;
    }

    static int mod_inv(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return val; }

    mod_int& operator+=(const mod_int &o) {
        val += o.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    mod_int& operator-=(const mod_int &o) {
        val -= o.val;
        if (val < 0) val += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
        return x % m;
    }

    mod_int& operator*=(const mod_int &o) {
        val = fast_mod((uint64_t)val * o.val);
        return *this;
    }

    mod_int& operator/=(const mod_int &o) {
        return *this *= o.inv();
    }

    friend mod_int operator+(const mod_int &a, const mod_int &b) { return mod_int(a) += b; }
    friend mod_int operator-(const mod_int &a, const mod_int &b) { return mod_int(a) -= b; }
    friend mod_int operator*(const mod_int &a, const mod_int &b) { return mod_int(a) *= b; }
    friend mod_int operator/(const mod_int &a, const mod_int &b) { return mod_int(a) /= b; }

    mod_int& operator++() { val = (val == MOD - 1) ? 0 : val + 1; return *this; }
    mod_int& operator--() { val = (val == 0) ? MOD - 1 : val - 1; return *this; }
    mod_int operator++(int) { mod_int before = *this; ++*this; return before; }
    mod_int operator--(int) { mod_int before = *this; --*this; return before; }
    mod_int operator-() const { return val ? MOD - val : 0; }

    bool operator==(const mod_int &o) const { return val == o.val; }
    bool operator!=(const mod_int &o) const { return val != o.val; }

    mod_int inv() const { return mod_inv(val); }

    mod_int pow(long long p) const {
        assert(p >= 0);
        mod_int a = *this, res = 1;
        while (p > 0) {
            if (p & 1) res *= a;
            a *= a;
            p >>= 1;
        }
        return res;
    }
};

const int N_MAX = 7;
int N;
mod_int prob[N_MAX][N_MAX];

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> N;

    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            int p; cin >> p;
            prob[i][j] = mod_int(p) / mod_int(100);
        }

    vector<vector<int>> masks_by_cnt(N_MAX + 1);
    vector<int> idx_map(1 << N, -1);

    for (int mask = 0; mask < 1 << N; mask++) {
        int cnt = __builtin_popcount(mask);
        idx_map[mask] = masks_by_cnt[cnt].size();
        masks_by_cnt[cnt].push_back(mask);
    }

    map<long long, mod_int> dp;
    dp[1LL << idx_map[0]] = 1;

    for (int left = 0; left < N; left++) {
        map<long long, mod_int> ndp;

        for (int cur = 0; cur < 1 << N; cur++) {
            mod_int prod = 1;
            for (int right = 0; right < N; right++)
                prod *= ((cur >> right) & 1) ? prob[left][right] : (1 - prob[left][right]);

            for (auto &[state, p] : dp) {
                long long st = state;
                mod_int cur_p = p;

                long long nst = 0;
                for (int mask : masks_by_cnt[left]) {
                    if ((st >> idx_map[mask]) & 1) {
                        for (int i = 0; i < N; i++) {
                            if (((cur >> i) & 1) && !((mask >> i) & 1)) {
                                nst |= 1LL << idx_map[mask | (1 << i)];
                            }
                        }
                    }
                }
                ndp[nst] += cur_p * prod;
            }
        }
        dp = move(ndp);
    }

    mod_int ans = 0;
    long long full_mask = (1LL << N) - 1;
    for (auto &[state, p] : dp) {
        if ((state >> idx_map[full_mask]) & 1) {
            ans += p;
        }
    }
    cout << (int)ans << '\n';
}
